//Current property being parsed
String stepPageProp = tools.getParamValue("pyForEachCount");
ClipboardPage  stepPage = tools.getStepPage();
String PropertyName = tools.getStepPage().getString("pxCurrentReference");

//Check what is the mode of the property
ClipboardProperty propForMode = tools.findPage("PostProsSnapOfWorkpage").getProperty(tools.getParamValue("Prefix") + PropertyName.substring(0,PropertyName.lastIndexOf('(')));
String propMode = propForMode.getModeName();

//Sort only if its page list
//get the subscript
 if(propMode=="Page List")
  {
  //Get the index from the bracket
  int leftmost_position  = PropertyName.lastIndexOf('(');
  int rightmost_position = PropertyName.lastIndexOf(')');
  String subscript = PropertyName.substring(leftmost_position+1,rightmost_position);
  int num = Integer.parseInt(subscript);
       for(int i=1;i<Integer.parseInt(stepPageProp);i++)
       {

       //Now need to check if the current property is page list of that type
        ClipboardPage tempPage = tools.findPage("CompareResultPage").getProperty("pxResults").getPageValue(i);

        String refProperty = tempPage.getString("pxCurrentReference");


       if(refProperty.contains(PropertyName.substring(0,PropertyName.lastIndexOf('(')+1)))
         {
           leftmost_position  = refProperty.lastIndexOf('(');
           rightmost_position = refProperty.lastIndexOf(')');

          subscript = refProperty.substring(leftmost_position+1,rightmost_position);
          int innerNum = Integer.parseInt(subscript);

          if(innerNum > num) //lets swap pages
          {

            //we need to swap when the stepPage's index is less than inner loop's ith positin elements index
            // we will swap element of ith position(inner loop) with element of pyForEachCount(step page)

            tools.getProperty("CompareResultPage.pxResults").remove(Integer.parseInt(stepPageProp));
            tools.getProperty("CompareResultPage.pxResults").add(Integer.parseInt(stepPageProp),tempPage);

             tools.getProperty("CompareResultPage.pxResults").remove(i);
             tools.getProperty("CompareResultPage.pxResults").add(i,stepPage);
           }
         }
       }         
   }

int num =1; 
boolean isPageList;
ClipboardPage currentPage = null;
isPageProp=false;
String PropName = tools.getStepPage().getStringIfPresent("pxCurrentReference");
  oLog.debug("PropName--->>>"+PropName);
String propMode = "";
//if and only if its a pagelist/page group property, proceed i.e if the reference has ")"
if(PropName!=null && PropName.charAt(PropName.length()-1)==')')
  {
String modeProp= PropName.substring(0,PropName.lastIndexOf('(')-1);
ClipboardProperty propForMode = tools.findPage("PostProsSnapOfWorkpage").getProperty(tools.getParamValue("Prefix") + PropName.substring(0,PropName.lastIndexOf('(')));
 propMode = propForMode.getModeName();
  oLog.debug("propForMode--->>>"+propForMode.getReference());
  oLog.debug("propMode--->>>"+propMode);

if(propMode=="Page List" || propMode=="Page Group" )
  {
  //Either a Pagelist or a PageGroup Property Exist
    isPageProp=true;

 //Get the index/subsscript from the bracket
  int leftmost_position  = PropName.lastIndexOf('(');
  int rightmost_position = PropName.lastIndexOf(')');
  String subscript = PropName.substring(leftmost_position+1,rightmost_position);
   //For Page_list type , get the page using the page number/index number
  if(propMode=="Page List")
    {
    num = Integer.parseInt(subscript);

    ClipboardProperty listProp = tools.findPage("PostProsSnapOfWorkpage").getProperty(tools.getParamValue("Prefix") + PropName.substring(0,leftmost_position));
    currentPage = listProp.getPageValue(num); 
    oLog.debug(currentPage.getXML());
   } //For Page Group, get the page using the page subscript
  else if(propMode=="Page Group")
    {
    ClipboardProperty listProp = tools.findPage("PostProsSnapOfWorkpage").getProperty(tools.getParamValue("Prefix") + PropName.substring(0,leftmost_position));
     currentPage = listProp.getPageValue(subscript);   
  }


  //we need to recall the pxComparePagesWrapper and pass current page and an a empty page, so that all the differences comes
  ClipboardPage tempCurrentPage = tools.createPage("Work-", "tempCurrentPage"); 
  if(currentPage!= null){
  tempCurrentPage.replace(currentPage);   //Current Page 
  }
  //Now, we have to call compare page api, to compare this result again with a blank page
  ClipboardPage blankPage = tools.createPage("Work-", "blankPage");  //Compare With Page

  //Set the Prefix Value, which will be added before each property
  // PrefixVal = PropName.substring(1,PropName.length());
  PrefixVal = PropName;
}  

}

// this code is for handling page properties SE-57452
if (PropName!=null){

  ClipboardProperty property = tools.findPage("PostProsSnapOfWorkpage").getProperty(tools.getParamValue("Prefix") + PropName);
  if(property!=null)
     propMode = property.getModeName();
  oLog.debug("propMode--->>>"+propMode);  
if("Page".equals(propMode)){
    isPageProp=true;       
     currentPage = tools.findPage("PostProsSnapOfWorkpage").getProperty(PropName).getPageValue();
    //we need to recall the pxComparePagesWrapper and pass current page and an a empty page, so that all the differences comes
  ClipboardPage tempCurrentPage = tools.createPage("Work-", "tempCurrentPage"); 
  if(currentPage!= null){
  tempCurrentPage.replace(currentPage);   //Current Page 
  }
  //Now, we have to call compare page api, to compare this result again with a blank page
  ClipboardPage blankPage = tools.createPage("Work-", "blankPage");  //Compare With Page

  //Set the Prefix Value, which will be added before each property
  // PrefixVal = PropName.substring(1,PropName.length());
  PrefixVal = PropName;


}

}

String PropName=tools.getStepPage().getStringIfPresent("pxCurrentReference");
String PropValue="";

try{
if(PropName != "" && PropName != null){
PropValue=tools.findPage("PostProsSnapOfWorkpage").getString(tools.getParamValue("Prefix")+PropName);
}
}catch(Exception ex)
  {
  oLog.error(ex);
}

if(PropValue!="")
  {
ClipboardProperty cb_property = tools.findPage("FlowTCRecordMode").getProperty("pyInputList");
ClipboardPage cb_page = cb_property.getPageValue(cb_property.size());

//Now, create a page with propety value pair, and set in in the pyExpectedResults property of the above page

ClipboardPage temp_ = tools.createPage("Embed-ExpectedResults","");

 temp_.putString("pyDTPropertyName",tools.getParamValue("Prefix")+PropName);
 temp_.putString("pyDTPropertyValue",PropValue);


    cb_page.getProperty("pyExpectedResults").add(temp_);  
}
